#include <iostream>

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}
};

bool search_bst(TreeNode* root, int key) {
    if (root == nullptr) return false;
    if (root->val == key) return true;
    if (key < root->val) return search_bst(root->left, key);
    return search_bst(root->right, key);
}

int main() {
    TreeNode root(10);
    TreeNode left(5);
    TreeNode right(15);
    root.left = &left;
    root.right = &right;
    bool found = search_bst(&root, 5);
    std::cout << "Found: " << found << std::endl;
    return 0;
}

