#include <stdio.h>

void reverse_array(int arr[], int size) {
    int start = 0;
    int end = size - 1;
    while (start < end) {
        int tmp = arr[start];
        arr[start] = arr[end];
        arr[end] = tmp;
        start++;
        end--;
    }
}

int main() {
    int nums[] = {1, 2, 3, 4, 5};
    reverse_array(nums, 5);
    printf("First: %d\n", nums[0]);
    return 0;
}

